//! Generated by `scripts/gen_benches.py`: times `lean_runtime::semantics::net::ntop_v6`; the
//! native twin is `benches/native/Bench/NetNtopV6.lean`.
//! 16 addresses built before the timed region; Lean's Array.get! retains and releases the address
//! it reads; the result is one new string object (the Rust twin formats on the stack; Lean's C
//! formats with snprintf and makes the string with lean_mk_string)

#![allow(unused_parens, unused_imports, unused_variables, unused_mut)]
#![allow(
    clippy::double_parens,
    clippy::unnecessary_cast,
    clippy::redundant_closure
)]
#![allow(clippy::identity_op, clippy::let_and_return)]

use lean_runtime::semantics::net;
use lean_runtime_bench::*;
use std::hint::black_box;

#[inline(never)]
fn kernel(inp: &Vec<[u16; 8]>, n: u64) -> u64 {
    let xs = &inp[..];
    let (mut x, mut acc) = (SEED, 0u64);
    for _ in 0..n {
        x = step(x);
        acc = mix(acc, {
            let mut b = StackBuf::new();
            let _ = net::ntop_v6(get_ipv6(xs, x >> 60), &mut b);
            make_ascii_string(b.as_bytes()).byte_size()
        });
    }
    acc
}

fn main() {
    run(|| ipv6_addrs(), kernel)
}
